/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _isRespin: false,  //是否处于repsin小游戏中
        _collect: null,
    },

    init(deskInfo,gameId,gameJackpot){
        this._super(deskInfo,gameId,gameJackpot);
        this.setCollectData(deskInfo.collect);
    },

    getRandomSymbol() {
        let cfg = cc.vv.gameData.getGameCfg();
        let symbols = cfg.randomSymbols;
        if (this._isRespin) {
            symbols = [3, 13, 13];
        }
        return symbols[Global.random(0, symbols.length-1)];
    },

    //设置是否处于respin小游戏中
    setRespin(val) {
        this._isRespin = val;
    },
    //是否是第一次触发免费
    isFirstTriggerFree() {
        return this.GetFreeTime() > 0 && this.GetFreeTime() == this.GetTotalFree();
    },
    //是否是最后一轮免费(旋转完成)
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },
    //免费赢得金币
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },
    //收集数据
    setCollectData(collect) {
        if (collect) {
            this._collect = collect;
        }
    },
    //收集数据
    getCollectData() {
        return this._collect;
    },
    //收集解锁押注等级
    getUnlockIdx() {
        return this.getCollectData().min;
    },
    //收集是否解锁
    isLocked() {
        return this.GetBetIdx() < this.getUnlockIdx();
    },
    //收集增加booster
    addCollectBooster(booster) {
        if (!this._collect.extra) this._collect.extra = [];
        this._collect.extra.push(booster);
    },
    //发送小游戏操作数据
    sendGameData(data_) {
        let req = {c: MsgId.SLOT_SUBGAME_DATA,
            gameid: this._gameId,
            data: data_
        };
        cc.vv.NetManager.send(req, true);
    }
});
