const BONUS_STATE = {
    NULL: 0,
    UNKNOW: 1,
    UNOPEN: 2,
    OPENED: 3,
}

cc.Class({
    extends: cc.Component,

    properties: {
        _jp_sandian_01: null,
        _jp_sandian_02: null,
        _pick_dj: null,  //点击动画
        _pick_award: null, //奖励动画
        _bonuses:[],
        _processing: false,
        _jp: 1,
        _spin_cnt:0,
        _pick_cnt:0,

        _pick_dj: null,
        _pick_award: null,
        _fly: null,
        _flash: null,
        _effect_layer: null,
    },

    onLoad () {
        this._jp_sandian_01 = cc.find("Canvas/safe_node/layout/jackpot/jp_sandian_01");
        this._jp_sandian_02 = cc.find("Canvas/safe_node/layout/jackpot/jp_sandian_02");
        let layout = this.node.getChildByName("layout");
        this._bonuses = [];
        for (let i=1; i<=15; i++) {
            let bonus_node = layout.getChildByName("bonus"+i);
            bonus_node.on("click", function () {
                this.onClickBonus(bonus_node)
            }, this);
            this._bonuses[i] = {
                node: bonus_node,
                lbl_coin: bonus_node.getChildByName("lbl_coin").getComponent(cc.Label),
                bonus_bg: bonus_node.getChildByName("bonus_bg"),
                diamond: bonus_node.getChildByName("diamond"),
                pick: bonus_node.getChildByName("pick"),
                state: BONUS_STATE.UNKNOW,
            };
            bonus_node.active = true;
        }
        this._respin_dj = this.node.getChildByName("respin_dj");
        this._pick_dj = this.node.getChildByName("pick_dj");
        this._pick_award = this.node.getChildByName("pick_award");
        //特效层，需要在整个场景最上层
        this._effect_layer = cc.find("Canvas/safe_node/effect_layer");
        this._fly = this._effect_layer.getChildByName("fly");
        this._flash = this._effect_layer.getChildByName("flash");

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, this);
    },

    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, false, this);
    },    

    ShowBonusState(bonus, state, coin) {
        if (state == BONUS_STATE.NULL) {
            bonus.node.active = false;
            return;
        }
        bonus.node.active = true;
        bonus.lbl_coin.node.active = false;
        bonus.bonus_bg.active = false;
        bonus.pick.active = false;
        bonus.diamond.active = false;
        bonus.state = state;
        if (state == BONUS_STATE.UNKNOW) {
            bonus.diamond.active = true;
        } else if (state == BONUS_STATE.UNOPEN) {
            bonus.pick.active = true;
            let ske = bonus.pick.getComponent(sp.Skeleton);
            ske.setAnimation(0, "animation1", false);
            ske.addAnimation(0, "animation2", true);
        } else if (state == BONUS_STATE.OPENED) {
            bonus.lbl_coin.node.active = true;
            bonus.lbl_coin.node.color = cc.Color.WHITE;
            bonus.lbl_coin.string = coin?Global.convertNumToShort(coin, 1000, 0):"";
            bonus.bonus_bg.active = true;
            bonus.bonus_bg.color = cc.Color.WHITE;
        }
    },

    //显示中奖金币
    ShowBounsCoin(bonus, coin) {
        bonus.lbl_coin.node.active = true;
        bonus.lbl_coin.string = coin?Global.convertNumToShort(coin, 1000, 0):"";
        bonus.lbl_coin.node.stopAllActions();
        bonus.lbl_coin.node.scale = 0.1;
        bonus.lbl_coin.node.runAction(cc.scaleTo(0.2, 1));
    },

    //显示spin状态
    ShowSpin(data) {
        Global.TheUnicorn.Slots.ShowReelsEmpty();  //卷轴显示空
        this.node.active = true;
        for (let i=1; i<=15; i++) {
            this.ShowBonusState(this._bonuses[i], BONUS_STATE.NULL);
        }
        this.UpdateSpin(data, true);
    },
    //更新spin状态
    async UpdateSpin(data, init) {
        this._spin_cnt = data.spin;
        this.SetSpinCnt(this._spin_cnt);
        if (init) {
            this.SetJackpot(data.pool);
        } else {
            await this.UpdateJackpot(data.pool);
        }
        if (data.cards) {
            for (let i=0; i<data.cards.length; i++) {
                if (data.cards[i] == 3) {
                    this.ShowBonusState(this._bonuses[i+1], BONUS_STATE.UNKNOW);
                } else {
                    this.ShowBonusState(this._bonuses[i+1], BONUS_STATE.NULL);
                }
            }
        }
        cc.vv.gameData.SetRespinTime(data.spin);
    },

    //显示pick状态
    ShowPick(data) {
        this._processing = false;
        Global.TheUnicorn.Slots.ShowReelsEmpty();  //卷轴显示空
        this.node.active = true;
        this._pick_cnt = data.pick;
        this.SetPickCnt(this._pick_cnt);
        if (data.cards) {
            for (let i=0; i<data.cards.length; i++) {
                if (data.cards[i] == 3) {
                    this.ShowBonusState(this._bonuses[i+1], BONUS_STATE.UNOPEN);
                } else {
                    this.ShowBonusState(this._bonuses[i+1], BONUS_STATE.NULL);
                }
            }
        }
        if (data.indexs && data.indexs.all) {
            for (let i=0; i<data.indexs.all.length; i++) {
                this.ShowBonusState(this._bonuses[data.indexs.all[i]], BONUS_STATE.UNOPEN);
            }
        }
        if (data.result && data.result.pick) {
            for (let i=0; i<data.result.pick.length; i++) {
                let info = data.result.pick[i];
                this.ShowBonusState(this._bonuses[info.idx], BONUS_STATE.OPENED, info.coin);
            }
        }
        Global.SlotsSoundMgr.playEffect("bonus/bonus_change");
        this.setAutoPlay();
    },

    Hide() {
        this._jp_sandian_01.active = false;
        this._jp_sandian_02.active = false;
        this.node.active = false;
    },

    setAutoPlay(){
        let list = [];
        for (let i=1; i<=15; i++) {
            if(this._bonuses[i].state == BONUS_STATE.UNOPEN){
                list.push(this._bonuses[i].node);
            }
        }
        if(list.length > 0){
            let randomIdx = Global.random(0,list.length-1);
            let self = this;
            cc.vv.gameData.checkAutoPlay(list[randomIdx],  function (){self.onClickBonus(list[randomIdx])});
        }
    },

    onClickBonus(node) {
        if (this._processing) return;
        for (let i=1; i<=15; i++) {
            this._bonuses[i].node.stopAllActions();
            if (node == this._bonuses[i].node && this._bonuses[i].state == BONUS_STATE.UNOPEN) {
                this.SetPickCnt(this._pick_cnt-1);
                cc.vv.gameData.sendGameData({rtype:4, idx:i});
                this._processing = true;
                break;
            }
        }
    },

    //设置Respin次数
    SetCnt(cnt, desc) {
        cnt = Math.max(0, cnt);
        cc.find("progress/lbl_cnt", this.node).getComponent(cc.Label).string = ""+cnt;
        let atlas = cc.vv.gameData.GetAtlasByName("base");
        let txt = desc + "_1";
        if (cnt > 1) {
            txt = desc + "_2";
        }
        cc.find("progress/txt_remaining", this.node).getComponent(cc.Sprite).spriteFrame
            = atlas.getSpriteFrame(txt);
    },
    //设置spin次数
    SetSpinCnt(cnt) {
        this.SetCnt(cnt, "theme140_respin_2");
    },
    OnStartSpin(){
        this.SetSpinCnt(this._spin_cnt-1);
    },
    //设置pick次数
    SetPickCnt(cnt) {
        this.SetCnt(cnt, "theme140_respin_3");
    },

    async UpdateJackpot(jp) {
        if (this._jp != jp) {
            this._jp_sandian_02.active = true;
            this._jp_sandian_02.position = cc.find("prizePool_"+jp, this._jp_sandian_02.parent).position;
            let name = jp > 8 ? "animation1" : "animation2";
            this._jp_sandian_02.getComponent(sp.Skeleton).setAnimation(0, name, false);
            await this.Sleep(0.5);
            this.SetJackpot(jp);
            Global.SlotsSoundMgr.playEffect("bonus/bonus_reset");
        }
    },

    //设置当前奖池索引
    SetJackpot(jp) {
        this._jp = jp;
        if (jp > 0) {
            this._jp_sandian_01.active = true;
            this._jp_sandian_01.position = cc.find("prizePool_"+jp, this._jp_sandian_01.parent).position;
            let name = jp > 8 ? "animation1" : "animation4";
            this._jp_sandian_01.getComponent(sp.Skeleton).setAnimation(0, name, true);
        } else {
            this._jp_sandian_01.active = false;
        }
    },

    async Sleep(time) {
        return new Promise((resolve, reject) => {
            this.scheduleOnce(()=>{resolve()}, time);
        });
    },

    //点击动画
    async playClickAni(pos) {
        this._respin_dj.active = true;
        this._respin_dj.position = pos;
        this._respin_dj.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        await this.Sleep(0.3);
        this._pick_dj.active = true;
        this._pick_dj.position = pos;
        this._pick_dj.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        Global.SlotsSoundMgr.playEffect("bonus/pick_click");
    },

    //animation1: moveup
    //animation2_1 animation2_2 animation2_3: prize upgrede
    //animation3: pick+1
    //animation4: pick+2 
    playAwardAni(pos, ani) {
        this._pick_award.active = true;
        this._pick_award.position = pos;
        this._pick_award.getComponent(sp.Skeleton).setAnimation(0, ani, false);
    },

    //飞行动画
    playFlyAni(from_wp, to_wp){
        let from = this._effect_layer.convertToNodeSpaceAR(from_wp);
        let to = this._effect_layer.convertToNodeSpaceAR(to_wp);
        let fly = cc.instantiate(this._fly);
        fly.parent = this._effect_layer;
        fly.position = from;
        fly.active = true;
        fly.runAction(cc.sequence(
            cc.moveTo(0.5, to),
            cc.fadeOut(0.1),
            cc.destroySelf())
        );
    },

    //流光动画
    async playFlashAni(from_wp, to_wp) {
        let from = this._effect_layer.convertToNodeSpaceAR(from_wp);
        let to = this._effect_layer.convertToNodeSpaceAR(to_wp);
        this._flash.active = true;
        //设置缩放和角度
        let v = cc.v2(to.x, to.y).sub(cc.v2(from.x, from.y));
        let length = v.mag();
        this._flash.scale = length/220;
        let angle = v.signAngle(cc.v2(1, 0));
        this._flash.angle = -angle * cc.macro.DEG - 90;
        this._flash.position = from;
        //播放动画
        let ske = this._flash.getComponent(sp.Skeleton);
        ske.setAnimation(0, "animation", false);
    },

    async OpenBonus(info, pick, pool, picks){
        let bonus = this._bonuses[info.idx];
        let pos = bonus.node.position;
        let from_wp = bonus.node.convertToWorldSpaceAR(cc.v2(0,0));
        //播放打开动画
        await this.playClickAni(pos);
        await this.Sleep(0.5);
        this.ShowBonusState(bonus, BONUS_STATE.OPENED);

        if (info.prize == 1) {  //金币奖励
            this.ShowBounsCoin(bonus, info.coin);
        } else if (info.prize == 2) {  //奖金翻倍
            this.playAwardAni(pos, "animation2_1");  //播放中奖动画
            await this.Sleep(0.5);
            for (let i=0; i<picks.length; i++) {
                let idx = picks[i].idx
                if (idx != info.idx) {
                    this.playAwardAni(pos, "animation2_2");   //播放图标闪烁
                    Global.SlotsSoundMgr.playEffect("bonus/pick_upgrade");
                    await this.Sleep(0.3);
                    this.playFlashAni(from_wp, this._bonuses[idx].node.convertToWorldSpaceAR(cc.v2(0,0)));  //播放流光动画
                    await this.Sleep(0.3);
                    this.ShowBounsCoin(this._bonuses[idx], picks[i].coin);  //显示金币数值
                    await this.Sleep(0.2);
                }
            }
            this.playAwardAni(pos, "animation2_3");
        } else if (info.prize == 3 || info.prize == 4) { //pick+1  pick+2
            this.playAwardAni(pos, "animation"+info.prize);
            await this.Sleep(0.5);
            Global.SlotsSoundMgr.playEffect("bonus/pick_increase");
            let lbl_cnt = cc.find("progress/lbl_cnt", this.node);
            let to_wp = lbl_cnt.convertToWorldSpaceAR(cc.v2(0, 0));
            this.playFlyAni(from_wp, to_wp);
            await this.Sleep(0.5);
            let zj = cc.find("progress/zj", this.node);
            zj.active = true;
            zj.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            await this.Sleep(0.5);
        }else if (info.prize == 5) { //jackpot+1
            this.playAwardAni(pos, "animation1");
            await this.Sleep(0.5);
            Global.SlotsSoundMgr.playEffect("bonus/pick_jp");
            let jpnode = cc.find("Canvas/safe_node/layout/jackpot/prizePool_"+this._jp);
            if (jpnode) {
                let to_wp = jpnode.convertToWorldSpaceAR(cc.v2(0, 0));
                this.playFlyAni(from_wp, to_wp);
                await this.Sleep(0.5);
                await this.UpdateJackpot(pool);
            } else {
                cc.warn("prizePool_"+this,_jp+" not exist");
            }
        }

        this._pick_cnt = pick;
        this.SetPickCnt(this._pick_cnt);
        this.ShowBounsCoin(bonus, info.coin);
    },

    async ShowResult(data) {
        //先翻牌
        for (let i=0; i<data.result.other.length; i++) {
            let info = data.result.other[i];
            let bonus = this._bonuses[info.idx];
            this.ShowBonusState(bonus, BONUS_STATE.OPENED, info.coin);
            bonus.bonus_bg.color = cc.Color.GRAY;
            bonus.lbl_coin.node.color = cc.Color.GRAY;
        }
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playEffect("bonus/bonus_end");
        // 显示2秒
        await this.Sleep(2);
        // 播放流光
        let wincoin = 0;
        let winBg = cc.find("Canvas/safe_node/LMSlots_Bottom/winBg");
        let to_wp = winBg.convertToWorldSpaceAR(cc.v2(0,0));
        for (let i=0; i<data.result.pick.length; i++) {
            let info = data.result.pick[i];
            let bonus = this._bonuses[info.idx];
            let from_wp = bonus.node.convertToWorldSpaceAR(cc.v2(0,0));
            this.playFlyAni(from_wp, to_wp);
            Global.SlotsSoundMgr.playEffect("bonus/pick_hit");
            await this.Sleep(0.5);
            wincoin += info.coin;
            cc.vv.gameData.GetBottomScript().SetWin(wincoin);
            await this.Sleep(0.4);
        }
        //奖池流光
        let jpnode = cc.find("Canvas/safe_node/layout/jackpot/prizePool_"+this._jp);
        if (jpnode) {
            let from_wp = jpnode.convertToWorldSpaceAR(cc.v2(0, 0));
            this.playFlashAni(from_wp, to_wp);
            Global.SlotsSoundMgr.playEffect("bonus/bonus_jp");
        }
        await this.Sleep(0.5);
        cc.vv.gameData.GetBottomScript().SetWin(data.coin);
    },

    async OnMsgPick(msg) {
        let data = msg.data;
        await this.OpenBonus(data.info, data.pick, data.pool, data.result.pick);
        
        if (data.pick <= 0) { //结束
            //显示中奖结果
            await this.ShowResult(data);
            //显示赢钱
            cc.vv.gameData.AddCoin(data.coin);
            await Global.TheUnicorn.Pop.showRespinEnd(data.coin);
            //显示换场
            Global.TheUnicorn.Pop.showTransition("qieping2");
            await this.Sleep(1.2);
            //切换卷轴
            Global.TheUnicorn.Slots.ShowNormalReels();
            this.Hide();
            Global.SlotsSoundMgr.playNormalBgm(true);
            await new Promise(resolve=>{
                Global.TheUnicorn.Slots.ShowBottomWin(data.coin, data.coin, true, resolve);
            });
            Global.TheUnicorn.Slots.CanDoNextRound();
        }

        this._processing = false;
        this.setAutoPlay();
    },

    OnRecvMsgSubAction(msg){
        if (msg.code == 200 && msg.data.rtype == 4) {
            this.OnMsgPick(msg);
        }
    },

});
