        _wheelData:null,
        _wheelResult:null,

        _freeStartClicked:false,
        _freeEndClicked:false,
        _wheelStartClicked:false,
        _wheelEndClicked: false,
        _superFreeStartClicked:false,
        _superFreeEndClicked:false,
