    async OnMsgSuperFree(msg) {
        if (this._superFreeStartClicked) return;
        this._superFreeStartClicked = true;
        Global.showAlertAction(this._frame, false, 1, 0.1, ()=>{
            this._pop.active = false;
            this._frame.active = false;
            this._super_free_start.active = false;
            this.PlayRoleAnimation("animation2", false);
            Global.SlotsSoundMgr.playEffect("free/bison_down");
            this._superFreeStartClicked = false;
        });

        await this.Sleep(0.6);
        this.showTransition("qieping1");
        Global.SlotsSoundMgr.playEffect("base/transition_free");

        await this.Sleep(1.0);
        Global.TheUnicorn.Slots.ResizeReels(msg.data.col, msg.data.row);
        Global.TheUnicorn.Slots.ShowGameview(true);
    },

    OnRecvMsgSubAction(msg){
        if (msg.code == 200 && msg.data.rtype == 2) { //超级免费
            this.OnMsgSuperFree(msg);
        }
    },

