/*
 * 收集游戏
*/
cc.Class({
    extends: cc.Component,

    properties: {
        _collect:null,
        _map:null,
        _bar:null,
        _pos:null,
        _tip:null,
        _islock:false,
        _processing:false,
        _show:false,
        _idx:0,
    },

    onLoad () {
        // 收集进度
        this._collect = cc.find("safe_node/slots/collect", this.node);
        this._collect.on("click", this.onClickCollect.bind(this));
        this._bar = cc.find("progress_bg/progress/bar", this._collect);
        this._pos = cc.find("progress_bg/progress/pos", this._collect);
        this._tip = cc.find("tip", this._collect);
        let btnMap = cc.find("ball/map", this._collect);
        btnMap.on("click", this.onClickMap.bind(this));
        this.onEventTotalbetUpdated();
        
        //地图
        this._map = cc.find("safe_node/map", this.node);
        let btnBack = cc.find("layout/btn_back", this._map);
        btnBack.on("click", this.onClickBack.bind(this));

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)
    },

    start() {
        this.refreshProgress();
        this.refreshMap();
    },

    async Sleep(time) {
        return new Promise((resolve, reject) => {
            this.scheduleOnce(()=>{resolve()}, time);
        });
    },

    //设置进度条 value: 0~1
    setProgress(value, anim) {
        value = Math.min(Math.max(0, value), 1);
        let x = value * 500;
        if (anim) {
            this._bar.runAction(cc.moveTo(0.1, x, 0));
            this._pos.x = x;
            this._pos.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        } else {
            this._bar.x = x;
        }
    },

    //更新进度
    refreshProgress() {
        let data = cc.vv.gameData.getCollectData();
        this.setProgress(data.num/data.total);

        //图标
        let idx = data.idx;
        let frame = "theme140_collect_nextStep_5";
        if (idx == 3) {
            frame = "theme140_collect_nextStep_1";
        } else if (idx == 7) {
            frame = "theme140_collect_nextStep_2";
        } else if (idx == 12) {
            frame = "theme140_collect_nextStep_3";
        } else if (idx == 18) {
            frame = "theme140_collect_nextStep_4";
        }
        let atlas = cc.vv.gameData.GetAtlasByName("base");
        cc.find("progress_bg/next_step", this._collect).getComponent(cc.Sprite).spriteFrame
         = atlas.getSpriteFrame(frame);
    },

    //更新地图
    refreshMap() {
        let atlas = cc.vv.gameData.GetAtlasByName("map");
        let data = cc.vv.gameData.getCollectData();
        let idx = data.idx;  //当前所处关卡
        this._idx = idx;
        if (idx<1) idx = 1;
        
        let ends = [4, 8, 13, 19];  //大关卡
        let ends_booster = [2, 3, 4, 5]; //大关卡的bosster
        for (let i=0; i<4; i++) {
            let end = cc.find("layout/end"+ends[i], this._map);
            if (idx >= ends[i]) {
                //已完成
                end.getChildByName("completed").active = true;
                end.getChildByName("booster").active = false;
                end.getChildByName("frame").active = false;
            } else if (idx>1 && idx<ends[i] && (i==0 || idx>ends[i-1])) {
                //进行中
                end.getChildByName("completed").active = false;
                end.getChildByName("booster").active = true;
                end.getChildByName("frame").active = true;
                let cnt = 0;
                if (i==0) cnt = idx - 1;
                else cnt = idx - ends[i-1];
                for (let j=1; j<=ends_booster[i]; j++) {
                    let booster = cc.find("booster/booster"+j, end);
                    if (j<=cnt) {
                        booster.active = true;
                        if (data.extra.indexOf(j) >= 0) {  //获得
                            booster.getChildByName("state").getComponent(cc.Sprite).spriteFrame
                             = atlas.getSpriteFrame("theme140_map_right");
                        } else {  //未获得
                            booster.getChildByName("state").getComponent(cc.Sprite).spriteFrame
                             = atlas.getSpriteFrame("theme140_map_wrong");
                        }
                    } else {
                        booster.active = false;
                    }
                }
            } else {
                //未开始
                end.getChildByName("completed").active = false;
                end.getChildByName("booster").active = false;
                end.getChildByName("frame").active = true;
            }
        }

        //闪烁动画
        let pos = cc.find("layout/pos", this._map);
        pos.active = (ends.indexOf(idx)==-1);
        //小关
        for (let i=1; i<=19; i++) {
            if (ends.indexOf(i) != -1) continue;
            let p = cc.find("layout/p"+i, this._map);
            if (i<=idx) {
                p.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme140_map_end5");
            } else {
                p.getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme140_map_end5_1");
            }
            if (i==idx) {
                pos.position = cc.v2(p.x-4, p.y+4);
                pos.getComponent(sp.Skeleton).setAnimation(0, "animation2", true);
            }
        }
    },

    onEventTotalbetUpdated() {
        let islock = cc.vv.gameData.GetBetIdx() < cc.vv.gameData.getUnlockIdx();
        if (islock!=this._islock) {
            this._islock = islock;
            if (islock) {
                this._collect.getChildByName("lock").getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
            } else {
                this._collect.getChildByName("lock").getComponent(sp.Skeleton).setAnimation(0, "animation4", false);
                Global.SlotsSoundMgr.playEffect("base/unlock");
            }
        }
    },

    onClickCollect() {
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime()>0) return;
        if (cc.vv.gameData.GetFreeTime()>0) return;
        if (this._islock) {
            let unlockidx = cc.vv.gameData.getUnlockIdx();
            cc.vv.gameData.GetBottomScript().SetBetIdx(unlockidx);
        }
        this.showTips();
    },

    onClickMap() {
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime()>0) return;
        if (cc.vv.gameData.GetFreeTime()>0) return;
        if (!this._islock) {
            let data = cc.vv.gameData.getCollectData();
            if (this._idx != data.idx) {
                this.refreshMap();
            }
            this.showMap(true, false);
        }
    },

    onClickBack() {
        this.showMap(false);
    },

    showTips() {
        this._tip.stopAllActions();
        if (this._tip.opacity > 0) {
            this._tip.runAction(cc.fadeOut(0.2));
        } else {
            this._tip.runAction(cc.sequence(cc.fadeIn(0.1), cc.delayTime(5), cc.fadeOut(0.2)));
        }
    },

    async showMap(bshow, upgrade) {
        if (this._show==bshow) return;
        this._show = bshow;
        this._processing = false;
        cc.vv.gameData.GetBottomScript().ShowInputMask(bshow);

        let layout = this._map.getChildByName("layout");
        layout.stopAllActions();
        if (bshow) {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.playEffect("map/map_open");

            this._map.active = true;
            layout.y = 1600;
            layout.runAction(cc.moveTo(0.4, 0, 0));

            //路径
            let idx = cc.vv.gameData.getCollectData().idx;
            let path =  cc.find("layout/path", this._map);
            let ske = path.getComponent(sp.Skeleton);
            if (upgrade) { //升级
                cc.find("layout/btn_back", this._map).active = false;

                await this.Sleep(0.5);
                path.active = true;
                ske.setAnimation(0, "animation"+(idx-1), false);
                ske.addAnimation(0, "animation"+(idx-1)+"_1", false);
                let ends = [4, 8, 13, 19];  //大关卡
                if (ends.indexOf(idx) >= 0) {
                    Global.SlotsSoundMgr.playEffect("map/map_move2");
                } else {
                    Global.SlotsSoundMgr.playEffect("map/map_move1");
                }
                await this.Sleep(0.5);
                this.refreshMap();
                await this.Sleep(2.5);
                this.onClickBack();
            } else {
                if (idx > 1) {
                    path.active = true;
                    ske.setAnimation(0, "animation"+(idx-1)+"_1", false);
                } else {
                    path.active = false;
                }
                cc.find("layout/btn_back", this._map).active = true;
            }
        } else {
            cc.vv.gameData.GetBottomScript().CanDoNextRound();

            Global.SlotsSoundMgr.playEffect("map/map_close");
            layout.runAction(cc.sequence(cc.moveTo(0.3, 0, 1600), cc.callFunc(()=>{
                this._map.active = false;
            })));
        }
    },

});
