
cc.Class({
    extends: cc.Component,

    properties: {
        _wheel_node: null,
        _wheel_wheel: null,
        _btn_spin: null,
        _data: null,
    },

    onLoad() {
        this._wheel_node = cc.find("safe_node/wheel", this.node);
        this._wheel_wheel = cc.find("layout/wheel", this._wheel_node);
        this._btn_spin = cc.find("layout/btn_spin", this._wheel_node);
        this._btn_spin.on('click', this.onClickSpin.bind(this));

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, this);
    },

    start() {
        //this.showSpin({idx:Global.random(1,4)});
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.OnRecvMsgSubAction, false, this);
    },

    formatNumber(num) {
        if (num < 10000000) {
            return Global.FormatNumToComma(Math.floor(num / 1000)) + 'K';
        } else {
            return Global.FormatNumToComma(Math.floor(num / 1000000)) + 'M';
        }
    },

    showSpin(res) {
        this._btn_spin.getComponent(cc.Button).interactable = true;
        this._btn_spin.getChildByName("zp_01").active = true;
        this._wheel_wheel.angle = 0;
        this._wheel_node.active = true;
        let layout = this._wheel_node.getChildByName("layout");
        cc.find("result", layout).active = false;

        Global.showAlertAction(layout, true, 0.1, 1, null);
        Global.SlotsSoundMgr.playEffect("map/wheel_in");

        let atlas = cc.vv.gameData.GetAtlasByName("wheel");
        for (let i = 0; i < res.length; i++) {
            let info = res[i];
            this._wheel_wheel.getChildByName("lbl_coin" + (i + 1))
                .getComponent(cc.Label).string = this.formatNumber(info.num);
            if (i == 0) {
                this._wheel_wheel.getChildByName("booster")
                    .getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame("theme140_wheel_booster" + info.extra);
            }
        }

        Global.SlotsSoundMgr.playBgm("map/wheel_bgm");

        cc.vv.gameData.checkAutoPlay(this._btn_spin, () => {
            Global.SlotsSoundMgr.playEffect("base/common_click");
            this._btn_spin.getComponent(cc.Button).interactable = false;
            this._btn_spin.getChildByName("zp_01").active = false;
            cc.vv.gameData.sendGameData({ rtype: 1 });
        })
    },

    hide() {
        let layout = this._wheel_node.getChildByName("layout");
        Global.showAlertAction(layout, true, 0.1, 1, () => {
            this._wheel_node.active = false;
            Global.SlotsSoundMgr.playNormalBgm(true);
        });
        Global.SlotsSoundMgr.playEffect("map/wheel_out");
    },

    onClickSpin(event) {
        Global.SlotsSoundMgr.playEffect("base/common_click");
        this._btn_spin.getComponent(cc.Button).interactable = false;
        this._btn_spin.stopAllActions();
        this._btn_spin.getChildByName("zp_01").active = false;
        cc.vv.gameData.sendGameData({ rtype: 1 });
    },

    //开始旋转
    StartSpin(data) {
        let self = this;
        let idx = data.idx;
        let count = 4;
        let rot = 8 * 360 + (count - (idx - 1)) * (360 / count);
        let zp_03 = this._btn_spin.getChildByName("zp_03");
        zp_03.active = true;
        zp_03.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        this._wheel_wheel.runAction(cc.sequence(
            cc.delayTime(1.25),
            cc.callFunc(() => {
                Global.SlotsSoundMgr.playEffect("map/wheel_spin");
            }),
            cc.rotateTo(6, rot).easing(cc.easeQuadraticActionInOut()),
            cc.callFunc(() => {
                //停下，显示结果
                cc.find("layout/result", self._wheel_node).active = true;
                Global.SlotsSoundMgr.playEffect("map/wheel_end");
            }),
            cc.delayTime(2.5),
            cc.callFunc(() => {
                //弹出提示
                Global.TheUnicorn.Pop.showWheelEnd(data.result);
            }),
        ));
        /*
        cc.tween(this._wheel_wheel)
            .delay(1.25)
            .call(()=>{
                Global.SlotsSoundMgr.playEffect("map/wheel_spin");
            })
            .to(6, {angle:-rot}, {easing:"quadInOut"})
            .delay(0.5)
            .call(() => {
                //停下，显示结果
                cc.find("layout/result", self._wheel_node).active = true;
                Global.SlotsSoundMgr.playEffect("map/wheel_end");
            })
            .delay(2.5)
            .call(() => {
                //弹出提示
                Global.TheUnicorn.Pop.showWheelEnd(data.result);
            })
            .start();
        */
    },

    OnRecvMsgSubAction: function (msg) {
        if (msg.code == 200 && msg.data.rtype == 1) { //抽奖结果
            let data = msg.data.data;
            this.StartSpin(data);
            if (data.result.extra) {
                cc.vv.gameData.addCollectBooster(data.result.extra);
            }
        }
    },

});
