/**
 * slots
 */
 let SCATTER = 2;
 let BONUS = 3;
 let WILD_X1 = 1;
 let WILD_X2 = 14;
 let EMPTY = 13;
 let SCALE_6_COL = 5/6;

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _wilds:[],
        _lbl_free_cnt:null,
        _lbl_total_cnt:null,
        _wild_move: null,
        _respin: null,
        _jp_sandian: null,
        _is_respin: false,
        _is_super_free:false,
    },

    Init:function(){
        this._sw = 130;
        this._sh = 112;
        this._wild_move = this.node.getChildByName("wild_move").getComponent("TheUnicorn_WildMove");
        this._respin = this.node.getChildByName("respin").getComponent("TheUnicorn_Respin");
        this._super();
    },

    //刷新widget
    OnReelResized(node) {
        var widget = cc.Node.isNode(node) && node.getComponent(cc.Widget);
        if (widget) {
            if (widget.alignMode === cc.Widget.AlignMode.ON_WINDOW_RESIZE) {
                widget.enabled = true;
            }
        }
        var children = node._children;
        for (var i = 0; i < children.length; i++) {
            var child = children[i];
            this.OnReelResized(child);
        }
    },

    ResizeReels(col, row) {
        if (!(col>=5&&col<=6&&row>=3&&row<=4)) return;
        if (this._col == col && this._row == row) return;
        this._col = col;
        this._row = row;
        let origin_symbol_width = 130;
        let origin_symbol_height = 112;
        let scale = 5 / col;
        let symbol_width = origin_symbol_width * scale;
        let symbol_height = origin_symbol_height * scale;
        let width = symbol_width * col;
        let height = symbol_height * row;

        //slots框体大小调整
        cc.find("reels_bg", this.node).height = height;
        cc.find("reels", this.node).height = height;
        cc.find("reels_frame", this.node).height = height;
        cc.find("wild_move", this.node).height = height;
        
        //是否显示第6列
        cc.find("reels_bg/reel_bg6", this.node).active = (col>=6);
        cc.find("reels/reel6", this.node).active = (col>=6);

        //处理topani层
        this._topAniNode.scale = scale;
        for (let i=0; i<this._reels.length; i++) {
            let reel = this._reels[i];
            for (let j=0; j<reel._symbols.length; j++) {
                reel._symbols[j].setAnimationToTop(false);
            }
        }
        this._topAniNode.destroyAllChildren();

        //增减列
        if (this._reels.length < col) {
            let reelCmp = this._cfg.scripts.Reels;
            let node = cc.find("reels/reel6", this.node);
            let scp = node.getComponent(reelCmp);
            if (!scp) {
                scp = node.addComponent(reelCmp);
                scp.Init(5, row, this._topAniNode);
            }
            this._reels.push(scp);
        } else if (this._reels.length > col) {
            this._reels.pop();
        }

        //设置每列symbol个数
        for (let i=0; i<this._reels.length; i++) {
            this._reels[i].SetCount(row);
        }

        //holder缩放
        for (let i=1; i<=col; i++) {
            cc.find("reels/reel"+i+"/mask/holder", this.node).scale = scale;
        }

        //wild move缩放
        cc.find("wild_move/layout", this.node).scale = scale;
        this._wild_move.SetCol(col);
        this._wild_move.SetRow(row);

        this.OnReelResized(this.node);
        for (let i=1; i<=5; i++) {
            cc.find("reels_bg/reel_bg"+i+"/line", this.node).x = (symbol_width-1)/2;
        }
    },

    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []
        this._wilds = [];
        for(let i = 0;i < cards.length; i++){
            if (cards[i]==WILD_X1 || cards[i]==WILD_X2) {
                this._wilds.push(i+1);
            }
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i]
                res.data = (cards[i]==BONUS)
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        for(let j = 0; j < this._reels.length; j++){
            let item = this._reels[j]
            let reelRes = reelResults[j]
            item.SetResult(reelRes)
        }
    },

    async Sleep(time) {
        return new Promise((resolve, reject) => {
            this.scheduleOnce(()=>{resolve()}, time);
        });
    },

    //显示钻石收集
    ShowDiamondFly(fromWp) {
        if (!this._diamond) {
            this._diamond = cc.instantiate(this.node.getChildByName("diamond"));
        }
        if (!this._diamondEndPos) {
            let icon = cc.find("collect/icon", this.node);
            this._diamondEndPos = this.node.convertToNodeSpaceAR(icon.convertToWorldSpaceAR(cc.v2(0,0)));
        }
        let diamond = cc.instantiate(this._diamond);
        diamond.active = true;
        diamond.getComponent(sp.Skeleton).setAnimation(0, "animation", true);
        let pos = this.node.convertToNodeSpaceAR(fromWp);
        diamond.position = pos;
        diamond.parent = this.node;
        diamond.runAction(cc.sequence(cc.moveTo(0.5, this._diamondEndPos), cc.destroySelf()));
    },
    //设置卷轴背景
    SetReelsBg(name) {
        // todo 换皮游戏中只有一种卷轴背景背景
        // let atlas = cc.vv.gameData.GetAtlasByName("base");
        // for (let i=1; i<=5; i++) {
        //     cc.find("reels_bg/reel_bg"+i, this.node).getComponent(cc.Sprite).spriteFrame
        //      = atlas.getSpriteFrame(name);
        // }
    },

    //显示所有卷轴为空符号
    ShowReelsEmpty() {
        for (let i=0; i<this._reels.length; i++) {
            let reel = this._reels[i];
            for (let j=0; j<reel._symbols.length; j++) {
                reel._symbols[j].ShowById(EMPTY);
            }
        }
    },

    //显示钻石小游戏卷轴
    ShowRespinReels(data) {
        //备份卷轴
        this.Backup();
        //隐藏收集条
        cc.find("collect", this.node).active = false;
        //游戏背景
        cc.find("Canvas/safe_node/bg_respin").active = true;
        //奖池背景
        // cc.find("Canvas/safe_node/layout/jackpot/liuguang").getComponent(sp.Skeleton)
        //   .setAnimation(0, "animation", true);
        //卷轴背景
        this.SetReelsBg("theme140_reel06");
        //清除顶层动画
        this._topAniNode.destroyAllChildren();
        //显示spin状态
        if (!data) data = this._gameInfo.bonusData;
        this._respin.ShowSpin(data);
        this._is_respin = true;
        cc.vv.gameData.setRespin(true);
    },

    //显示普通游戏卷轴
    ShowNormalReels() {
        cc.find("collect", this.node).active = true; //显示收集条
        cc.find("Canvas/safe_node/bg_respin").active = false;
        // cc.find("Canvas/safe_node/layout/jackpot/liuguang").getComponent(sp.Skeleton)
        //   .setAnimation(0, "animation1", true);
        this.SetReelsBg("theme140_reel6");
        
        //恢复卷轴
        this.Resume();
        this._is_respin = false;
        cc.vv.gameData.setRespin(false);
    },

    //显示收集钻石
    async ShowCollectDiamond() {
        if (this._is_respin) return;
        if (!this._gameInfo.collect) return;
        if (cc.vv.gameData.isLocked()) return;

        let diamond = false;
        for (let i=0; i<this._reels.length; i++) {
            let reel = this._reels[i];
            for (let j=0; j<reel._symbols.length; j++) {
                let symbol = reel._symbols[j]
                if (symbol.GetData()) {
                    this.ShowDiamondFly(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                    diamond = true;
                }
            }
        }
        if (diamond) {
            Global.SlotsSoundMgr.playEffect("base/fly");
            await this.Sleep(0.5);
            let spine = cc.find("collect/icon/spine", this.node);
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            //更新进度条
            await this.Sleep(0.2);
            let c = this._gameInfo.collect;
            Global.TheUnicorn.Collect.setProgress(c.num/c.total, true);
        }
    },

    StartSuperFree() {
        let freeCnt = 10;
        if (cc.vv.gameData.getCollectData().extra.indexOf(1)>=0) {
            freeCnt = 15;
        }
        cc.vv.gameData.SetFreeTime(freeCnt);
        cc.vv.gameData.SetTotalFree(freeCnt);
        Global.TheUnicorn.Pop.showSuperFreeStart(freeCnt);
        this._is_super_free = true;
    },

    async AfterSpinEnd() {
        this.UpdateCollectMap(true);
        //显示收集钻石
        await this.ShowCollectDiamond();

        // 显示中奖路线
        this._gameInfo.scatterZJLuXian = null; //不显示scatter路线
        this.ShowWinTrace();

        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(resolve=>{
           this.ShowBottomWin(nWin,nTotal,true, resolve);
        });

        //钻石小游戏中
        let bonusData = this._gameInfo.bonusData;
        if (this._is_respin && bonusData && bonusData.cards != null) {
            await this._respin.UpdateSpin(bonusData);
        }

        let can_spin = true;
        //触发免费游戏
        if (cc.vv.gameData.isFirstTriggerFree()) {
            this.playSymbolAnimation(SCATTER, "win");
            this._wilds = []; //wilds先清空
            can_spin = false;
            this._bottomScript.ShowBtnsByState("moveing_1");
            await this.Sleep(0.8);
            Global.TheUnicorn.Pop.showFreeStart(cc.vv.gameData.GetFreeTime());
            this.Backup();
        }
        //结束免费游戏
        if (cc.vv.gameData.isLastEndFree()) {
            this._wilds = []; //wilds先清空
            this._wild_move.Clear();  //清空移动节点
            can_spin = false;
            this._bottomScript.ShowBtnsByState("moveing_1");
            if (this._is_super_free) {
                Global.TheUnicorn.Pop.showSuperFreeEnd(cc.vv.gameData.GetGameTotalFreeWin());
            } else {
                Global.TheUnicorn.Pop.showFreeEnd(cc.vv.gameData.GetGameTotalFreeWin());
            }
            this._is_super_free = false;
        }
        //开始bonus小游戏
        if (this._gameInfo.select && this._gameInfo.select.state == true) {
            can_spin = false;
            let sel = this._gameInfo.select;
            this._bottomScript.ShowBtnsByState("moveing_1");
            if (sel.rtype == 3) {  //钻石spin开始
                this.playSymbolAnimation(BONUS, "trigger");
                cc.vv.gameData.sendGameData({rtype:3});
                await this.Sleep(0.8);
                await Global.TheUnicorn.Pop.showRespinStart();
            } else if (sel.rtype == 4) {  //钻石pick开始
                this._respin.ShowPick(bonusData); //显示抽卡
                cc.vv.gameData.SetRespinTime(0);
            } else if (sel.rtype == 1) { //小关能量集满，触发转盘
                Global.SlotsSoundMgr.playEffect("map/full");
                Global.TheUnicorn.Pop.showWheelStart(this._gameInfo.collect.turn);
            } else if (sel.rtype == 2) { //大关能量集满，触发超级免费
                Global.SlotsSoundMgr.playEffect("map/full");
                this.StartSuperFree();
            }
        }

        if (can_spin) {
            this.CanDoNextRound()
            if (this._is_respin){
                this._bottomScript.ShowBtnsByState("moveing_1");
            }
        }
    },

    //wild移动结束
    OnWildMoveEnd() {
        this.SetStopTime(1.5);
    },

    //更新免费次数
    UpdateFreeCnt() {
        let total = cc.vv.gameData.GetTotalFree()
        if(total > 0){
            let rest = cc.vv.gameData.GetFreeTime()
            if (!this._lbl_free_cnt) this._lbl_free_cnt = cc.find("Canvas/safe_node/free/lbl_free_cnt").getComponent(cc.Label);
            this._lbl_free_cnt.string = ""+(total-rest); 
            if (!this._lbl_total_cnt) this._lbl_total_cnt = cc.find("Canvas/safe_node/free/lbl_total_cnt").getComponent(cc.Label);
            this._lbl_total_cnt.string = ""+total;
        }
    },

    UpdateCollectMap(val) {
        cc.find("collect/ball/map", this.node).getComponent(cc.Button).interactable = val;
    },

    //重写，开始旋转
    StartMove:function() {
        //开始播放背景音乐
        Global.SlotsSoundMgr.playNormalBgm();
        if (cc.vv.gameData.GetTotalFree()>0 && this._wilds.length>0) {
            this._wild_move.StartMove(this._wilds, this.OnWildMoveEnd.bind(this));
        }
        this.UpdateFreeCnt();
        this.UpdateCollectMap(false);
        if (this._is_respin) {
            this._respin.OnStartSpin();
        }

        this._super();
    },

    //重写，收到服务端数据
    onMsgSpine:function(msg){
        this._super(msg)
        if (this._gameInfo.collect) {
            cc.vv.gameData.setCollectData(this._gameInfo.collect);
        }
        if (this._gameInfo.freeWildIndexs && this._wild_move.IsMoving()) {
            this._wild_move.SetResult(this._gameInfo.freeWildIndexs.move);
            this.SetStopTime(20); //有moving  wilds 来控制停止
        }
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        this._wild_move.SetVisiable(false);
        this.AfterSpinEnd();
    },

    //重写
    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        if(bFree){
            Global.SlotsSoundMgr.playBgm('free/free_bgm');
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
        
            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            this.UpdateFreeCnt();
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            this._bottomScript.SetWin(nTotal)
            this.CanDoNextRound()
        } else {
            this._bottomScript.ShowFreeModel(false);          
        }

        cc.find("Canvas/safe_node/bg_base").active = !bFree;
        cc.find("Canvas/safe_node/bg_free").active = bFree;
        cc.find("Canvas/safe_node/layout/jackpot").active = !bFree;
        cc.find("Canvas/safe_node/free").active = bFree;
        cc.find("role", this.node).active = !bFree;
        cc.find("collect", this.node).active = !bFree;
        cc.find("logo", this.node).active = !bFree;
    },

    playSymbolAnimation(symbolId, ani) {
        for (let i=0; i<this._reels.length; i++) {
            let reel = this._reels[i];
            for (let j=0; j<this._row; j++) {
                let symbol = reel._symbols[j];
                if (symbol && symbol.GetShowId()==symbolId) {
                    if (ani == "win") {
                        symbol.playWinAnimation();
                    } else if (ani == "trigger") {
                        symbol.playTriggerAnimation();
                    }
                }
            }
        }
        Global.SlotsSoundMgr.playEffect("base/bell");
    },

    //重写
    ReconnectShow:function(){
        //免费游戏
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest){
            this.ShowGameview(true)
        } else {
            this.ShowGameview(false)
        }

        let deskInfo = cc.vv.gameData.getDeskInfo();
        let sel = deskInfo.select;
        if (sel && sel.state == true) {
            if (sel.rtype == 3) {  //钻石游戏
                this._bottomScript.ShowBtnsByState("moveing_1");
                cc.vv.gameData.sendGameData({rtype:3});
            } else if (sel.rtype == 1) {  //转盘游戏
                this._bottomScript.ShowBtnsByState("moveing_1");
                Global.TheUnicorn.Wheel.showSpin(deskInfo.collect.turn);
            } else if (sel.rtype == 2) {  //超级免费
                this.StartSuperFree();
            }
        }
        //钻石游戏-spin
        let bonusData = deskInfo.bonusData;
        if (bonusData && bonusData.spin && bonusData.spin > 0) {
            this.ShowRespinReels(bonusData);
            cc.vv.gameData.SetRespinTime(bonusData.spin);
            cc.vv.gameData.setRespin(true);
        }
        //钻石游戏-pick
        if (bonusData && bonusData.pick && bonusData.pick > 0) {
            this._bottomScript.ShowBtnsByState("moveing_1");
            this.ShowRespinReels(bonusData);
            this._respin.ShowPick(bonusData); //显示抽卡
            cc.vv.gameData.SetRespinTime(0);
        }

        //增加行列
        let collect = cc.vv.gameData.getCollectData();
        if (collect.col && collect.row) {
            this.ResizeReels(collect.col, collect.row);
        }
    },

    //重写
    DoCheckReelAnti:function(colIdx) {
        if (this._is_respin) return;  //钻石小游戏不要加速
        this._super(colIdx);
    }

});
