cc.Class({
    extends: cc.Component,

    properties: {
        _layout: null,
        _wildx1: null,
        _wildx2: null,
        _wilds:[],
        _result: null,
        _callback: null,
    },

    onLoad () {
        this._layout = this.node.getChildByName("layout");
        this._wildx1 = this.node.getChildByName("wildx1");
        this._wildx2 = this.node.getChildByName("wildx2");
        this._moving = false;
        this._sw = 130;
        this._sh = 112;
        this._col = 5;
        this._row = 3;
        this.SetVisiable(false);
    },

    //设置符号大小
    SetSymbolSize(width, height) {
        this._sw = width;
        this._sh = height;
    },

    SetCol(col) {
        this._col = col;
    },

    SetRow(row) {
        this._row = row;
    },

    //设置背景
    SetVisiable(val) {
        let opacity = 0;
        if (val) {
            opacity = 255;
        }
        this.node.opacity = opacity;
    },

    IsMoving() {
        return this._moving;
    },

    //idx 服务端card索引
    //x1: animation1
    //x2: animation2
    SetWilds(posIndexes, x2) {
        for (let i=0; i<posIndexes.length; i++) {
            if (!this._wilds[i]) {
                let wild = null;
                if (x2) {
                    wild = cc.instantiate(this._wildx2);
                } else {
                    wild = cc.instantiate(this._wildx1);
                }
                wild.parent = this._layout;
                wild.active = true;
                this._wilds[i] = wild;
            }
            this._wilds[i].position = this.GetPos(posIndexes[i]);
            this._wilds[i].zIndex = posIndexes[i];
        }
    },

    //card索引转换为坐标
    GetPos(idx) {
        let row = Math.floor((idx-1)/this._col);
        let col = Math.floor((idx-1)%this._col);
        let spaceX = col * 4;
        return cc.v2(col*this._sw+this._sw/2 + spaceX, (this._row-1-row)*this._sh+this._sh/2);

    },

    //开始移动
    StartMove(indexes, callback, x2) {
        Global.SlotsSoundMgr.playEffect("free/free_wild_land");
        this._moving = true;
        this.SetVisiable(true);
        this._result = null;
        this._callback = callback;
        this.SetWilds(indexes, x2);
        this._movecnt = 0;
        for (let wild of this._wilds) {
            let ske = wild.getComponent(sp.Skeleton)
            ske.setAnimation(0, "animation2", false);
            ske.addAnimation(0, "animation3", true);
        }
        this.MoveRandom();
    },

    //随机移动
    MoveRandom() {
        let movetime = 1.5;
        for (let wild of this._wilds) {
            wild.stopAllActions();
            let randpos = this.GetPos(Global.random(1, this._col * this._row));
            wild.runAction(cc.moveTo(movetime, randpos));
        }
        this.node.runAction(cc.sequence(cc.delayTime(movetime+0.05), cc.callFunc(this.OnMoveRoundEnd.bind(this))));
        Global.SlotsSoundMgr.playEffect("free/free_wild_run");
    },

    //移动到目标
    MoveToTarget() {
        let movetime = 1.5;
        for (let i=0; i<this._result.length; i++) {
            let wild = this._wilds[i];
            if (wild) {
                wild.stopAllActions();
                let pos = this.GetPos(this._result[i]);
                wild.runAction(cc.sequence(cc.moveTo(movetime, pos), cc.callFunc((sender)=>{
                    sender.getComponent(sp.Skeleton).setAnimation(0, "animation4", false);
                    Global.SlotsSoundMgr.stopEffectByName("free_wild_run");
                })));
            }
        }
        this.node.runAction(cc.sequence(cc.delayTime(movetime+0.05), cc.callFunc(this.OnMoveEnd.bind(this))));
        Global.SlotsSoundMgr.playEffect("free/free_wild_run");
    },

    //设置结果
    SetResult(res) {
        this._result = res;
    },

    //清理数据
    Clear() {
        this._layout.destroyAllChildren();
        this._wilds.length = 0;
    },

    //一轮移动结束
    OnMoveRoundEnd() {
        this._movecnt += 1;
        if (this._movecnt >= 2 && this._result) { //至少移动两次页服务端返回结果数据
            this.MoveToTarget();    
        } else {
            this.MoveRandom();
        }
    },

    //整个移动结束
    OnMoveEnd() {
        this._moving = false;
        if (this._callback) {
            this._callback();
        }
    },
});
